/* Business Graph Embedded Asset Fallback System */
window.BUSINESS_GRAPH_ASSETS = {"assets/logo.png":"data:image/png;base64,","assets/logo-icon.png":"data:image/png;base64,","assets/favicon.png":"data:image/png;base64,","assets/team/balakumaran.jpg":"data:image/jpeg;base64,","assets/team/nagaraj.jpg":"data:image/jpeg;base64,","assets/team/dharaneshwaran.jpg":"data:image/jpeg;base64,","assets/team/kavin.jpg":"data:image/jpeg;base64,","assets/team/vetrivel.jpg":"data:image/jpeg;base64,","assets/team/barath.jpg":"data:image/jpeg;base64,"};

(function() {
  function applyFallback(img) {
    if (!img) return;
    const rawSrc = img.getAttribute("src");
    if (!rawSrc) return;
    const matchKey = Object.keys(window.BUSINESS_GRAPH_ASSETS).find(function(k) {
      return rawSrc.endsWith(k) || rawSrc === k;
    });
    if (matchKey && window.BUSINESS_GRAPH_ASSETS[matchKey]) {
      const dataUri = window.BUSINESS_GRAPH_ASSETS[matchKey];
      img.onerror = function() {
        this.onerror = null;
        this.src = dataUri;
        this.classList.add("loaded-from-fallback");
      };
      if (img.complete && (img.naturalWidth === 0 || img.naturalHeight === 0)) {
        img.src = dataUri;
        img.classList.add("loaded-from-fallback");
      }
    }
  }

  function scanAll() {
    document.querySelectorAll("img").forEach(applyFallback);
  }

  window.addEventListener("error", function(e) {
    if (e && e.target && e.target.tagName === "IMG") {
      applyFallback(e.target);
    }
  }, true);

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", scanAll);
  } else {
    scanAll();
  }
  window.addEventListener("load", scanAll);
})();
